import{_ as i,a0 as o,w as t,s as d,I as a,x as n,a1 as l,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Lua 循环：如何使用 while 和 repeat until | LCTT x X-CMD","titleTemplate":false,"description":"Lua 循环：如何使用 while 和 repeat until | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Lua 循环：如何使用 while 和 repeat until | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Lua 循环：如何使用 while 和 repeat until | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230214.1 ⭐️ Lua loops how to use while and repeat until","title":"Lua 循环：如何使用 while 和 repeat until","tag":"202302","desc":""},"relativePath":"202302/20230214.1 ⭐️ Lua loops how to use while and repeat until.md","filePath":"[post].md"}'),u={name:"202302/20230214.1 ⭐️ Lua loops how to use while and repeat until.md"};function c(h,s,b,g,f,k){const e=o("Link");return t(),d("div",null,[s[32]||(s[32]=a("h1",{id:"lua-循环-如何使用-while-和-repeat-until",tabindex:"-1"},[n("Lua 循环：如何使用 while 和 repeat until "),a("a",{class:"header-anchor",href:"#lua-循环-如何使用-while-和-repeat-until","aria-label":"Permalink to “Lua 循环：如何使用 while 和 repeat until”"},"​")],-1)),s[33]||(s[33]=a("blockquote",null,[a("p",null,"学习如何以及何时在 Lua 中使用 while 和 repeat until 循环。")],-1)),a("p",null,[s[1]||(s[1]=n("控制结构是编程语言的一个重要特征，因为它们使你能够根据通常在程序运行时动态建立的条件来指导程序的流程。不同的语言提供了不同的控制，在 Lua 中，有 ",-1)),s[2]||(s[2]=a("code",null,"while",-1)),s[3]||(s[3]=n(" 循环、",-1)),s[4]||(s[4]=a("code",null,"for",-1)),s[5]||(s[5]=n(" 循环和 ",-1)),s[6]||(s[6]=a("code",null,"repeat",-1)),s[7]||(s[7]=n()),s[8]||(s[8]=a("code",null,"until",-1)),s[9]||(s[9]=n(" 循环。这篇文章涵盖了 ",-1)),s[10]||(s[10]=a("code",null,"while",-1)),s[11]||(s[11]=n(" 和 ",-1)),s[12]||(s[12]=a("code",null,"repeat until",-1)),s[13]||(s[13]=n(" 循环。由于它们的灵活性，我在一篇 ",-1)),l(e,{href:"https://opensource.com/article/22/11/lua-for-loops"},{default:p(()=>[...s[0]||(s[0]=[n("单独的文章",-1)])]),_:1}),s[14]||(s[14]=n(" 中介绍 ",-1)),s[15]||(s[15]=a("code",null,"for",-1)),s[16]||(s[16]=n(" 循环。",-1))]),s[34]||(s[34]=r(`<p>条件是由一个使用运算符的表达式来定义的，运算符是你在数学课上可能认识的符号的一个花哨的术语。Lua 中有效的运算符有：</p><ul><li><code>==</code> 等于</li><li><code>~=</code>不等于</li><li><code>&lt;</code> 小于</li><li><code>&gt;</code> 大于</li><li><code>⇐</code>小于或等于</li><li><code>&gt;=</code> 大于或等于</li></ul><p>这些被称为关系运算符，因为它们比较两个值之间的关联。还有一些逻辑运算符，其含义与英语中的含义相同，可以纳入条件中，进一步描述你想检查的状态：</p><ul><li><code>and</code></li><li><code>or</code></li></ul><p>下面是一些条件的例子：</p><ul><li><code>foo &gt; 3</code>：变量 <code>foo</code> 是否大于 3？<code>foo</code> 必须是 4 或更大才能满足这个条件。</li><li><code>foo &gt;= 3</code>：<code>foo</code> 是否大于或等于 3？<code>foo</code> 必须是 3 或更大才能满足这个条件。</li><li><code>foo &gt; 3 and bar &lt; 1</code>：<code>foo</code> 是否大于 3 而 <code>bar</code> 小于 1？要满足这个条件，<code>foo</code> 变量必须在 <code>bar</code> 为 0 的同时为 4 或更大。</li><li><code>foo&gt; 3 or bar &lt; 1</code>：<code>foo</code> 是否大于 3？或者，<code>bar</code> 是否小于 1？如果 <code>foo</code> 是 4 或更大，或者 <code>bar</code> 是 0，那么这个条件就是真的。如果 <code>foo</code> 是 4 或更大，而 <code>bar</code> 是 0，会怎样？答案出现在本文的后面。</li></ul><h3 id="while-循环" tabindex="-1">while 循环 <a class="header-anchor" href="#while-循环" aria-label="Permalink to “while 循环”">​</a></h3><p>只要满足某个条件，while 循环就会执行指令。例如，假设你正在开发一个应用来监测正在进行的僵尸末日。当没有剩余的僵尸时，就不再有僵尸末日了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zombie = 1024</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while (zombie &gt; 0) do</span></span>
<span class="line"><span>  print(zombie)</span></span>
<span class="line"><span>  zombie = zombie-1</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if zombie == 0 then</span></span>
<span class="line"><span>  print(&quot;No more zombie apocalypse!&quot;)</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>运行代码，看僵尸消失：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./while.lua</span></span>
<span class="line"><span>1024</span></span>
<span class="line"><span>1023</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>No more zombie apocalypse!</span></span></code></pre></div><h3 id="until-循环" tabindex="-1">until 循环 <a class="header-anchor" href="#until-循环" aria-label="Permalink to “until 循环”">​</a></h3><p>Lua 还有一个 <code>repeat</code> <code>until</code> 循环结构，本质上是一个带有 <code>catch</code> 语句的 <code>while</code> 循环。假设你在从事园艺工作，你想追踪还剩下什么可以收获的东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mytable = { &quot;tomato&quot;, &quot;lettuce&quot;, &quot;brains&quot; }</span></span>
<span class="line"><span>bc = 3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repeat</span></span>
<span class="line"><span>   print(mytable[bc])</span></span>
<span class="line"><span>   bc = bc - 1</span></span>
<span class="line"><span>until( bc == 0 )</span></span></code></pre></div><p>运行代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./until.lua</span></span>
<span class="line"><span>brains</span></span>
<span class="line"><span>lettuce</span></span>
<span class="line"><span>tomato</span></span></code></pre></div><p>这很有帮助!</p><h3 id="无限循环" tabindex="-1">无限循环 <a class="header-anchor" href="#无限循环" aria-label="Permalink to “无限循环”">​</a></h3><p>一个无限循环有一个永远无法满足的条件，所以它无限地运行。这通常是一个由错误逻辑或你的程序中的意外状态引起的错误。例如，在本文的开头，我提出了一个逻辑难题。如果一个循环被设定为 <code>foo &gt; 3 or bar &lt; 1</code> 运行 ，那么当 <code>foo</code> 为 4 或更大而 <code>bar</code> 为 0 时，会发生什么？</p><p>下面是解决这个问题的代码，为了以防万一，还使用了 <code>break</code> 语句安全捕获：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>foo = 9</span></span>
<span class="line"><span>bar = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while ( foo &gt; 3 or bar &lt; 1 ) do</span></span>
<span class="line"><span>  print(foo)</span></span>
<span class="line"><span>  foo = foo-1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -- safety catch</span></span>
<span class="line"><span>  if foo &lt; -800000 then</span></span>
<span class="line"><span>    break</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>你可以安全地运行这段代码，但它确实模仿了一个意外的无限循环。有缺陷的逻辑是 <code>or</code> 运算符，它允许这个循环在 <code>foo</code> 大于 3 和 <code>bar</code> 小于 1 的情况下继续进行。<code>and</code> 运算符有不同的效果，但我让你去探索。</p><p>无限循环实际上有其用途。图形应用使用技术上的无限循环来保持应用程序窗口的开放。我们没有办法知道用户打算使用这个程序多久，所以程序无限地运行，直到用户选择<strong>退出</strong>。在这些情况下使用的简单条件显然是一个总是被满足的条件。下面是一个无限循环的例子，为了方便起见，还是内置了一个安全陷阱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true do</span></span>
<span class="line"><span>  print(n)</span></span>
<span class="line"><span>  n = n+1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if n &gt; 100 then</span></span>
<span class="line"><span>  break</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>条件 <code>while true</code> 总是被满足，因为 <code>true</code> 总是为真。这是比写 <code>while 1 == 1</code> 或类似的永远为真的简洁方式。</p><h3 id="lua-中的循环" tabindex="-1">Lua 中的循环 <a class="header-anchor" href="#lua-中的循环" aria-label="Permalink to “Lua 中的循环”">​</a></h3><p>从示例代码中可以看出，尽管有不同的实现方式，但循环基本上都是朝着同一个目标工作。选择一个对你来说有意义的，并且在你需要执行的处理过程中效果最好的。以防万一你需要它：终止失控循环的键盘快捷键是 <code>Ctrl+C</code>。</p><hr>`,28)),a("p",null,[s[18]||(s[18]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/23/2/lua-loops-while-repeat-until"},{default:p(()=>[...s[17]||(s[17]=[n("https://opensource.com/article/23/2/lua-loops-while-repeat-until",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[19]||(s[19]=[n("Seth Kenlon",-1)])]),_:1}),s[24]||(s[24]=n(" 选题：",-1)),l(e,{href:"https://github.com/lkxed/"},{default:p(()=>[...s[20]||(s[20]=[n("lkxed",-1)])]),_:1}),s[25]||(s[25]=n(" 译者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[21]||(s[21]=[n("geekpi",-1)])]),_:1}),s[26]||(s[26]=n(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[22]||(s[22]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[29]||(s[29]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[27]||(s[27]=[n("LCTT",-1)])]),_:1}),s[30]||(s[30]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:p(()=>[...s[28]||(s[28]=[n("Linux中国",-1)])]),_:1}),s[31]||(s[31]=n(" 荣誉推出",-1))])])}const L=i(u,[["render",c]]);export{C as __pageData,L as default};
